cd /tmp/claude-0/-home-user-Claudinite/069dacaf-e52d-552a-8eba-eb307a729b50/scratchpad && node -e '
const fs = require("fs");
const lines = fs.readFileSync("bootstrap-log.jsonl","utf8").trim().split("\n").map(l=>JSON.parse(l));
let prev = null;
for (const e of lines) {
  const ts = e.timestamp;
  const t = e.type;
  let desc = "";
  if (t === "user") {
    const c = e.message?.content;
    if (typeof c === "string") desc = "USER: " + c.slice(0,120).replace(/\n/g," ");
    else if (Array.isArray(c)) {
      for (const part of c) {
        if (part.type === "tool_result") desc = "  tool_result len=" + JSON.stringify(part.content||"").length;
        else if (part.type === "text") desc = "USER: " + part.text.slice(0,120).replace(/\n/g," ");
      }
    }
  } else if (t === "assistant") {
    const c = e.message?.content||[];
    for (const part of c) {
      if (part.type === "tool_use") desc += `TOOL ${part.name} ${JSON.stringify(part.input).slice(0,140).replace(/\n/g," ")} | `;
      else if (part.type === "text") desc += "TEXT: " + part.text.slice(0,80).replace(/\n/g," ") + " | ";
    }
  } else desc = t;
  console.log(ts ? ts.slice(11,19) : "        ", t.padEnd(9), desc.slice(0,220));
}
' > timeline.txt 2>&1; wc -l timeline.txt; head -60 timeline.txt

