  const changed = [];
  if (workflows && convergeSchedulerWorkflow(root, fullName, stubText, secretNames)) changed.push(SCHEDULER_WORKFLOW);
  // In queue mode `stubText` IS the scheduler run stub (the CLI picks it by dispatch mode),
